// Identical harness for 3.1 / 4.1 / 4.1.1. Fixtures simulate speech, not GPU inference.
using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using V15Voice;
public static class RenderPipelineBenchmark {
 public static int Main(){try{string version=typeof(KokoroEngine).Assembly.GetName().Version.ToString();foreach(int mode in new[]{1,2}){string root=RenderPipelineFixture.Root(),source=RenderPipelineFixture.Source(root);string baselineHash="";for(int pass=0;pass<2;pass++){int starts=RenderPipelineFixture.Lines(root,"starts"),tts=RenderPipelineFixture.Lines(root,"requests"),tempo=RenderPipelineFixture.Lines(root,"ffmpeg-calls");var clock=Stopwatch.StartNew();RenderOptions options;var result=RenderPipelineFixture.Run(root,source,mode,out options);clock.Stop();if(!result.Rendered||result.Status!="FINAL_VERIFIED")throw new Exception(result.Error==null?result.Status:result.Error.ToString());string hash=StateFiles.Hash(result.Bundle.Wave);if(pass==0)baselineHash=hash;else if(hash!=baselineHash)throw new Exception("Cold/warm WAV PCM bytes differ");var original=BatchJob.Load(source).Cues;var final=Scripts.ParseSrt(File.ReadAllText(result.Bundle.Srt));if(Scripts.ToSrt(original)!=Scripts.ToSrt(final))throw new Exception("Source wording/timecode changed");Console.WriteLine("PIPELINE|"+version+"|"+mode+"|"+pass+"|"+clock.Elapsed.TotalMilliseconds.ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+"|"+(RenderPipelineFixture.Lines(root,"starts")-starts)+"|"+(RenderPipelineFixture.Lines(root,"requests")-tts)+"|"+(RenderPipelineFixture.Lines(root,"ffmpeg-calls")-tempo)+"|"+hash+"|"+result.Bundle.Reports.Length);}}return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
